import { flags } from '../config/flags';
import type { FeatureFlag } from '../config/flags';

export function useFeatureFlag(flag: FeatureFlag): boolean {
  return flags[flag] === true;
}

import type { ReactNode } from 'react';
import type { FeatureFlag as FeatureFlagName } from '../config/flags';
import { useFeatureFlag } from '../hooks/useFeatureFlag';

export interface FeatureFlagProps {
  flag: FeatureFlagName;
  children: ReactNode;
  fallback?: ReactNode;
}

export function FeatureFlag({ flag, children, fallback = null }: FeatureFlagProps): ReactNode {
  return useFeatureFlag(flag) ? children : fallback;
}
